UPDATE businesses SET description = 'Royale Eatery is a long-running burger restaurant on Long Street in the Cape Town CBD, known for a menu that lists more than fifty gourmet burger varieties alongside pizza and pasta options. The restaurant leans into a playful, decadent approach to comfort food, building burgers around inventive topping combinations rather than a conventional short list, which has made it a reliable stop for both locals grabbing a casual meal and visitors exploring Long Street''s restaurant strip.

Upstairs, the venue runs as Royale Kitchen from 7pm, giving the same address a second identity in the evenings with its own kitchen service. Being right on Long Street puts it within walking distance of the CBD''s bars, shops and guesthouses, so it draws a steady mix of after-work diners and late-night visitors. Bookings are recommended on weekend evenings when the street gets busy.', description_enriched_at = datetime('now') WHERE slug = 'royale-eatery-cape-town-cbd' AND description = 'Royale Eatery is a Long Street burger restaurant offering more than 50 gourmet burger varieties alongside pizza and pasta, with an upstairs Royale Kitchen serving from 7pm.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
