-- clarkes-bookshop-cape-town-cbd (general)
UPDATE businesses SET description = 'Clarke''s Bookshop is a secondhand and antiquarian bookshop on Long Street, trading since 1957 and recognised as one of Cape Town''s longest-running independent booksellers. Since the 1970s it has built a particular specialisation in Africana, sourcing and cataloguing rare South African and African material that is otherwise hard to find, a focus that has turned the shop into a research resource rather than just a retail outlet.

That reputation extends well beyond Cape Town: the shop has supplied rare material to international institutions including the British Library and Yale University, underlining the depth of its catalogue. Spread across Long Street''s historic shopfronts, it remains a destination for collectors, academics and casual browsers alike, the kind of shop where a short visit can easily stretch into an afternoon of shelf-by-shelf exploration.', description_enriched_at = datetime('now') WHERE slug = 'clarkes-bookshop-cape-town-cbd' AND description = 'Clarke''s Bookshop is a secondhand and antiquarian bookshop on Long Street, founded in 1957 and specialising in Africana since the 1970s, supplying rare material to institutions including the British Library and Yale University.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
